    def __init__(self):
        self.zipfiles = {}
        self.members = {}

    def get_zipfile(self, name):
        digits = name.split('-', 1)[0].split('.', 1)[0]
        item_id, batch_id = Cover.id_to_item_and_batch_id(digits)
        size = name.split('-', 1)[1][0].lower() if '-' in name else ''
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            zf = ZipFile(path, 'a', compression=ZIP_STORED, allowZip64=True)
            self.zipfiles[path] = zf
            self.members[path] = set(zf.namelist())
        return self.zipfiles[path]

